@startuml

class Airline {
  +name : string
}

class Airport {
  +name : string
  +address : string
  +runwayNumber : int
}

class Aircraft {
  +name : string
  +type : string
  +yearOfManufacture : int
  +nextInspectionDate : date
}

class PassengerPlane extends Aircraft {
  +numberOfSeats : int
}

class SeatCategory {
  +designation : string
  +offersEntertainment : boolean
  +numberOfSeats : int
}

class Flight {
  +flightNumber : string
  +date : date
}

class FlightExecution {
  +ticketNumber : string
  +price : float
  +upgradeDesired : boolean
}

class Passenger {
  +name : string
  +passportNumber : string
}

class Employee {
  +name : string
  +dateOfEmployment : date
}

class FlightAttendant extends Employee {
  +isChiefStewardess : boolean
}

class Pilot extends Employee {
  +license : string
}

Airline "1" -- "0..*" Aircraft
Airline "1" -- "0..*" Employee
Aircraft "0..1" -- "0..1" Airport : homeAirport
Aircraft "1" -- "0..*" Flight
Flight "1" -- "0..*" FlightExecution
Flight "1" -- "1" Airport : departureAirport
Flight "1" -- "1" Airport : destinationAirport
FlightExecution "0..*" -- "0..*" FlightAttendant
FlightExecution "0..*" -- "1" Pilot : captain
FlightExecution "0..*" -- "1..2" Pilot : co-pilot
FlightExecution "0..*" -- "0..*" Passenger
FlightExecution "0..*" -- "1" SeatCategory
PassengerPlane "1" *-- "0..*" SeatCategory
SeatCategory "1" -- "0..*" FlightExecution

@enduml

